(() => {
 const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const course=window.MATH_COURSE,lessons=course.sections.flatMap((s,g)=>s.lessons.map(l=>({...l,group:g}))),key='quantsense-mathematics-progress-v1';
 let completed=new Set(),last='units',index=0,values={},seed=42;
 try{const saved=JSON.parse(localStorage.getItem(key)||'{}');completed=new Set((saved.completed||[]).filter(x=>lessons.some(l=>l.id===x)));last=saved.last||last;}catch(e){}
 const save=()=>{try{localStorage.setItem(key,JSON.stringify({completed:[...completed],last:lessons[index].id}));}catch(e){$('#progress-note').textContent='Browser storage is unavailable; progress lasts for this visit only.';}};
 function updateProgress(){ $('#progress-label').textContent=`${completed.size} of ${lessons.length} lessons marked understood`;$('#course-progress').value=completed.size;$('#course-progress').max=lessons.length;document.querySelectorAll('#math-nav a').forEach(a=>a.classList.toggle('completed',completed.has(a.dataset.id))); }
 function navigation(){ $('#math-nav').innerHTML=course.sections.map((s,g)=>`<details data-group="${g}"><summary>${g+1}. ${esc(s.title)} <small>(${s.lessons.length})</small></summary>${s.lessons.map(l=>`<a href="#${l.id}" data-id="${l.id}">${esc(l.title)}</a>`).join('')}</details>`).join('');$('#course-map').innerHTML=course.sections.map((s,g)=>`<a href="#${s.lessons[0].id}"><b>${String(g+1).padStart(2,'0')} · ${esc(s.title)}</b><small>${s.lessons.length} lessons · ${esc(s.lessons[0].title)} → ${esc(s.lessons.at(-1).title)}</small></a>`).join('');updateProgress(); }
 function glossary(query=''){const terms=course.glossary.filter(t=>(t.term+' '+t.definition).toLowerCase().includes(query.toLowerCase()));$('#glossary-entries').innerHTML=terms.map(t=>`<dt>${esc(t.term)}</dt><dd>${esc(t.definition)}</dd>`).join('');$('#glossary-count').textContent=`${terms.length} definitions`;}
 const palette=['#cdf59a','#74d9da','#ffd287','#d2b8f6','#f39f9c','#91b9ff'];
 function chart(result){
  const all=result.curves.flatMap(c=>c.points);let xmin=Math.min(...all.map(p=>p[0])),xmax=Math.max(...all.map(p=>p[0])),ymin=Math.min(0,...all.map(p=>p[1])),ymax=Math.max(0,...all.map(p=>p[1]));
  if(xmin===xmax){xmin-=1;xmax+=1;}if(ymin===ymax){ymin-=1;ymax+=1;}const dx=xmax-xmin,dy=ymax-ymin;xmin-=dx*.05;xmax+=dx*.05;ymin-=dy*.08;ymax+=dy*.08;
  const W=Math.max(320,Math.min(860,$('#math-chart').clientWidth-30)),H=W<500?340:460,L=W<500?53:75,R=18,T=25,B=65,pw=W-L-R,ph=H-T-B;
  const geometric=['vectors','dot','matrix','rank','svd','eigen','pca','partial','gradient','hessian','jacobian','double','lagrange','cholesky','correlation','complex','copula'].includes(lessons[index].lab);
  if(geometric){const unit=Math.max((xmax-xmin)/pw,(ymax-ymin)/ph),cx=(xmin+xmax)/2,cy=(ymin+ymax)/2;xmin=cx-pw*unit/2;xmax=cx+pw*unit/2;ymin=cy-ph*unit/2;ymax=cy+ph*unit/2;}
  const X=x=>L+(x-xmin)/(xmax-xmin)*pw,Y=y=>T+(ymax-y)/(ymax-ymin)*ph,coords=points=>points.map(p=>`${X(p[0]).toFixed(2)},${Y(p[1]).toFixed(2)}`).join(' '),names=[...new Set(result.curves.map(c=>c.name))];
  let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-labelledby="plot-title plot-description"><title id="plot-title">${esc(lessons[index].title)} interactive visual</title><desc id="plot-description">${esc(result.xlabel)} on the horizontal axis; ${esc(result.ylabel)} on the vertical axis. ${esc(result.stats.map(s=>s.name+': '+QM.fmt(s.value)).join('. '))}. Detailed values appear in the calculation table.</desc>`;
  const tickCount=W<500?3:4,tick=x=>Math.abs(x)>=10000?x.toExponential(1):Number(x.toPrecision(3)).toString();
  for(let i=0;i<=tickCount;i++){const x=xmin+(xmax-xmin)*i/tickCount,y=ymin+(ymax-ymin)*i/tickCount;svg+=`<path d="M${X(x)},${T}V${H-B} M${L},${Y(y)}H${W-R}" stroke="#29483f" fill="none"/><text x="${X(x)}" y="${H-B+23}" fill="#b4cabb" text-anchor="middle" font-size="12">${esc(tick(x))}</text><text x="${L-10}" y="${Y(y)+4}" fill="#b4cabb" text-anchor="end" font-size="12">${esc(tick(y))}</text>`;}
  if(ymin<=0&&ymax>=0)svg+=`<path d="M${L},${Y(0)}H${W-R}" stroke="#577668"/>`;
  if(xmin<=0&&xmax>=0)svg+=`<path d="M${X(0)},${T}V${H-B}" stroke="#577668"/>`;
  for(const curve of result.curves){const col=palette[names.indexOf(curve.name)%palette.length];if(curve.type==='scatter')svg+=curve.points.map(p=>`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="${curve.points.length===1?6:3}" fill="${col}" opacity=".8"/>`).join('');else if(curve.type==='bar'){const gaps=curve.points.slice(1).map((p,i)=>p[0]-curve.points[i][0]).filter(x=>x>0),bw=Math.min(45,gaps.length?Math.min(...gaps)/(xmax-xmin)*pw*.7:25);svg+=curve.points.map(p=>`<rect x="${X(p[0])-bw/2}" y="${Math.min(Y(p[1]),Y(0))}" width="${bw}" height="${Math.max(.5,Math.abs(Y(p[1])-Y(0)))}" fill="${col}" opacity=".8"/>`).join('');}else if(curve.type==='area')svg+=`<polygon points="${coords(curve.points)}" fill="${col}" fill-opacity=".15" stroke="${col}" stroke-width="1"/>`;else svg+=`<polyline points="${coords(curve.points)}" fill="none" stroke="${col}" stroke-width="${curve.name.includes('grid')?1:2.5}" stroke-linejoin="round"/>`;}
  svg+=`<text x="${L+pw/2}" y="${H-14}" fill="#d1e2d6" text-anchor="middle" font-size="13">${esc(result.xlabel)}</text><text x="20" y="${T+ph/2}" transform="rotate(-90 20 ${T+ph/2})" fill="#d1e2d6" text-anchor="middle" font-size="13">${esc(result.ylabel)}</text></svg>`;
  $('#math-chart').innerHTML=svg;$('#math-legend').innerHTML=names.map((name,i)=>`<span style="--color:${palette[i%palette.length]}">${esc(name)}</span>`).join('');
 }
 function calculate(){const l=lessons[index],result=QM.compute(l.lab,values,seed);chart(result);$('#math-stats').innerHTML=result.stats.map(s=>`<div class="math-stat"><span>${esc(s.name)}</span><strong>${esc(QM.fmt(s.value))}</strong></div>`).join('');$('#calculation-body').innerHTML=result.steps.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('');$('#math-feedback').textContent=`In this setting, ${result.stats.map(s=>s.name.toLowerCase()+' is '+QM.fmt(s.value)).join('; ')}. ${result.insight||l.finance}`;$('#math-note').textContent=(result.note?result.note+' ':'')+'Illustrative model; inputs and units are shown above. Random experiments use seed '+seed+'.';document.querySelectorAll('.math-control output').forEach(o=>o.textContent=QM.fmt(values[o.dataset.key]));$('#calculation-caption').textContent='Calculation walkthrough for the current controls';}
 function render(){const l=lessons[index],s=course.sections[l.group];values=Object.fromEntries(QM.controls[l.lab].map(c=>[c.key,c.value]));seed=42;document.title=l.title+' · Mathematics for Quantitative Finance · Quant$ense';$('#chapter-label').textContent=`${l.group+1} / ${course.sections.length} · ${s.title}`;$('#lesson-title').textContent=l.title;$('#lesson-position').textContent=`Lesson ${index+1} of ${lessons.length}`;$('#lesson-story').textContent=l.story;$('#lesson-reason').textContent=l.reason;$('#lesson-equation').textContent=l.equation;$('#lesson-example').textContent=l.example;$('#lesson-experiment').textContent=l.experiment;$('#lesson-question').textContent=l.question;$('#lesson-answer').textContent=l.answer;$('#finance-connection').textContent=l.finance;$('#lesson-prereq').innerHTML=index?`Builds on <a href="#${lessons[index-1].id}">${esc(lessons[index-1].title)}</a>. Work through earlier chapters if the notation is unfamiliar.`:'Start here. You only need to be comfortable counting and comparing quantities; technical terms are defined in the glossary.';
  $('#resample-lab').hidden=!['cholesky','correlation','lln','montecarlo','intervals','regression','ridge','ar','stationarity','antithetic','martingale','brownian','ito','gbm','copula','bootstrap'].includes(l.lab);
  $('#math-controls').innerHTML=QM.controls[l.lab].map(c=>`<div class="math-control"><label for="math-${c.key}">${esc(c.label)} <output for="math-${c.key}" data-key="${c.key}">${c.value}</output></label><input id="math-${c.key}" type="range" min="${c.min}" max="${c.max}" step="${c.step}" value="${c.value}" data-key="${c.key}"><small><span>${c.min}</span><span>${c.max}</span></small></div>`).join('');
  $('#source-link').href=(l.source||s.source)[1];$('#source-link').textContent=(l.source||s.source)[0];$('#understood').checked=completed.has(l.id);$('#previous-lesson').disabled=index===0;$('#next-lesson').textContent=index===lessons.length-1?'Return to course map':'Next lesson →';
  document.querySelectorAll('#math-nav a').forEach(a=>{if(a.dataset.id===l.id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelectorAll('#math-nav details').forEach(d=>d.open=Number(d.dataset.group)===l.group||$('#lesson-search').value.length>0);
  const text=[l.title,l.story,l.reason,l.equation].join(' ').toLowerCase(),terms=course.glossary.filter(t=>text.includes(t.term.toLowerCase())).slice(0,8);$('#local-terms').innerHTML=terms.map(t=>`<a href="#course-glossary" data-term="${esc(t.term)}">${esc(t.term)}</a>`).join('');
  const base=QM.compute(l.lab,{},42).stats[0];$('#numeric-question').textContent=`Using the default controls (press Reset), calculate “${base.name}”. Enter the result to within 0.01, or within 1% for larger values.`;$('#numeric-input').value='';$('#numeric-result').textContent='';$('#numeric-solution').textContent=`The default result is ${QM.fmt(base.value)}. The live calculation table gives the component values; reset the controls before comparing with this answer.`;$('#numeric-check').onclick=()=>{const raw=$('#numeric-input').value,v=Number(raw),tol=Math.max(.01,Math.abs(base.value)*.01);$('#numeric-result').textContent=raw!==''&&Number.isFinite(v)&&Math.abs(v-base.value)<=tol?'That matches the default calculation. Now explain which input controls the result.':'Not yet. Reset the experiment and follow the calculation table, checking the units.';};calculate();save();updateProgress();
 }
 function route(){const id=decodeURIComponent(location.hash.slice(1)),found=lessons.findIndex(l=>l.id===id);if(found>=0){index=found;render();}else if(!id){index=Math.max(0,lessons.findIndex(l=>l.id===last));render();}else if(['course-map','course-glossary','course-scope','course-projects'].includes(id)){const panel=$('#'+id);if(panel?.tagName==='DETAILS')panel.open=true;}}
 navigation();glossary();index=Math.max(0,lessons.findIndex(l=>l.id===last));render();route();
 window.addEventListener('hashchange',()=>{route();if(lessons.some(l=>l.id===location.hash.slice(1)))$('#lesson-title').scrollIntoView({block:'start'});});
 $('#math-controls').addEventListener('input',e=>{if(e.target.dataset.key){values[e.target.dataset.key]=Number(e.target.value);calculate();}});
 $('#reset-lab').onclick=render;$('#resample-lab').onclick=()=>{seed+=1;calculate();};
 let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(calculate,100);});
 $('#lesson-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#math-nav a').forEach(a=>{const l=lessons.find(l=>l.id===a.dataset.id);a.hidden=![l.title,l.story,l.finance].join(' ').toLowerCase().includes(q);});document.querySelectorAll('#math-nav details').forEach(d=>{d.hidden=![...d.querySelectorAll('a')].some(a=>!a.hidden);d.open=!!q||Number(d.dataset.group)===lessons[index].group;});$('#search-status').textContent=`${document.querySelectorAll('#math-nav a:not([hidden])').length} lessons shown`;});
 $('#glossary-search').oninput=e=>glossary(e.target.value);$('#local-terms').onclick=e=>{if(e.target.dataset.term){$('#course-glossary').open=true;$('#glossary-search').value=e.target.dataset.term;glossary(e.target.dataset.term);}};
 $('#understood').onchange=e=>{if(e.target.checked)completed.add(lessons[index].id);else completed.delete(lessons[index].id);save();updateProgress();};$('#clear-progress').onclick=()=>{if(confirm('Clear only your saved mathematics progress on this browser?')){completed.clear();save();updateProgress();$('#understood').checked=false;}};
 $('#previous-lesson').onclick=()=>location.hash=lessons[Math.max(0,index-1)].id;$('#next-lesson').onclick=()=>location.hash=index===lessons.length-1?'course-map':lessons[index+1].id;
 $('#print-lesson').onclick=()=>window.print();
 window.MATH_APP={lessons,select:id=>{location.hash=id;},getState:()=>({lesson:lessons[index].id,values:{...values},seed}),compute:QM.compute};
})();
